/**
 * The stop watch (`reminders/cloud-agent-stop-watch.ts`): one one-shot
 * reminder per watched agent, bound to the session whose turn launched it.
 * The agent's status webhook fires it early, so the host wakes that
 * conversation once the agent's run stops. Nothing polls the agent.
 */
import { describeError } from "../../../internal/describe-error.js";
import extension from "../extension.js";
import stopWatch, { WATCH_WINDOW_HOURS, } from "../reminders/cloud-agent-stop-watch.js";
const WATCH_PURPOSE = "cloud_agent_stop_watch";
/** `channels/cursor-cloud-agents.ts`, which the mount exposes as `<ns>__cursor-cloud-agents`. */
const STOP_WEBHOOK_CHANNEL = "cursor-cloud-agents";
/**
 * The stop watch the platform arms in the same call as the launch, and the
 * channel the agent's status webhook targets. Undefined when this session
 * cannot be watched: see {@link watchInput}.
 */
export async function launchWatch(ctx, agentId) {
    const reminders = ctx.host.reminders;
    if (reminders?.createRequest === undefined) {
        return undefined;
    }
    const input = watchInput(ctx, agentId);
    if (input === undefined) {
        return undefined;
    }
    return {
        watch: await reminders.createRequest(input),
        channel: `${extension.namespace}__${STOP_WEBHOOK_CHANNEL}`,
    };
}
/**
 * Watch `agentId` from this conversation unless it already does. A follow-up
 * passes the run before it, and its watch replaces this conversation's
 * earlier watch on the agent; `replace` does the same with no run. False when this session cannot be watched (see
 * {@link watchInput}) or arming failed; the agent runs either way.
 */
export async function armWatch(ctx, agentId, options = {}) {
    const { previousRunId } = options;
    const replace = options.replace ?? previousRunId !== undefined;
    const reminders = ctx.host.reminders;
    const input = watchInput(ctx, agentId, previousRunId);
    if (reminders === undefined || input === undefined) {
        return false;
    }
    try {
        const armed = (await reminders.list({
            status: "armed",
            purpose: WATCH_PURPOSE,
            continuationToken: input.continuationToken,
        })).filter((reminder) => reminder.channelId === input.channelId && watched(reminder) === agentId);
        if (!replace) {
            if (armed.length > 0) {
                return true;
            }
        }
        else {
            // A watch from before the follow-up would wake on a late webhook for
            // the run before it, and then miss the follow-up run's stop.
            for (const reminder of armed) {
                await reminders.cancel(reminder.id, "cloud_agent_followed_up");
            }
        }
        await reminders.create(input);
        return true;
    }
    catch (error) {
        console.warn(`[cursor-cloud-agents] could not watch ${agentId}: ${describeError(error)}`);
        return false;
    }
}
/**
 * The one-shot watch on `agentId` for this session, at its deadline. Undefined
 * when the mount opted out, the host has no reminders, or the session has no
 * continuation key.
 */
function watchInput(ctx, agentId, previousRunId) {
    if (!extension.config.watchStops) {
        return undefined;
    }
    const unwatched = (reason) => {
        console.warn(`[cursor-cloud-agents] not watching ${agentId}: ${reason}`);
        return undefined;
    };
    if (ctx.host.reminders === undefined) {
        return unwatched("this host has no reminders");
    }
    const continuationToken = ctx.session.continuationKey;
    if (continuationToken == null) {
        return unwatched("the session has no continuation key");
    }
    const deadline = new Date(Date.now() + WATCH_WINDOW_HOURS * 3_600_000).toISOString();
    // Reminder args are JSON, so a missing previous run leaves the key out.
    const args = previousRunId === undefined ? { agentId, deadline } : { agentId, deadline, previousRunId };
    return {
        purpose: WATCH_PURPOSE,
        channelId: ctx.session.channelId,
        continuationToken,
        handler: stopWatch,
        args,
        at: deadline,
        // A fire during a turn waits for it instead of losing the wake.
        busyPolicy: "queueBehindTurn",
    };
}
/** Some watch on `agentId` is armed. */
export async function isWatched(ctx, agentId) {
    const reminders = ctx.host.reminders;
    if (reminders === undefined) {
        return false;
    }
    try {
        const armed = await reminders.list({ status: "armed", purpose: WATCH_PURPOSE });
        return armed.some((reminder) => watched(reminder) === agentId);
    }
    catch (error) {
        console.warn(`[cursor-cloud-agents] could not read the watch on ${agentId}: ${describeError(error)}`);
        return false;
    }
}
/** End every watch on `agentId`, whose run was stopped on purpose or never launched. */
export async function disarmWatches(ctx, agentId, reason = "cloud_agent_cancelled") {
    const reminders = ctx.host.reminders;
    if (reminders === undefined) {
        return;
    }
    try {
        for (const reminder of await reminders.list({ status: "armed", purpose: WATCH_PURPOSE })) {
            if (watched(reminder) === agentId) {
                await reminders.cancel(reminder.id, reason);
            }
        }
    }
    catch (error) {
        console.warn(`[cursor-cloud-agents] could not stop watching ${agentId}: ${describeError(error)}`);
    }
}
/** Fire every armed watch on `agentId` now; its run just stopped. */
export async function fireWatches(reminders, agentId) {
    if (reminders.fireNow === undefined) {
        return 0;
    }
    let fired = 0;
    for (const reminder of await reminders.list({ status: "armed", purpose: WATCH_PURPOSE })) {
        if (watched(reminder) === agentId) {
            await reminders.fireNow(reminder.id);
            fired += 1;
        }
    }
    return fired;
}
function watched(reminder) {
    return reminder.args?.agentId;
}
